import {Port,materials} from '../../core/index.js';
import {portQuaternion} from '../../modeling/parts.js';
import {THREE,box} from './geometry.js';
import {spec} from './dimensions.js';
export function socket(host,id){const cfg=spec.ports[id],frame=new THREE.Group();frame.name='Original HEX '+cfg.role+' actual white4contact receiving assembly';frame.position.fromArray(cfg.position);frame.quaternion.copy(portQuaternion(cfg.face));host.body.add(frame);const white=materials.plastic(0xe9e6d9,{roughness:.75}),tin=materials.metal(0xb8b7a9,{roughness:.43}),parts=[],walls=[],contacts=[],returns=[],feet=[],tails=[],b=(size,p,name,mat=white)=>{const o=box(frame,size,p,mat,'A045 '+cfg.role+' '+name);parts.push(o);return o;};
 for(const sign of[-1,1]){walls.push(b([.8,7.8,5.25],[sign*5.6,-3.9,0],'closed real lateral wall'));walls.push(b([1.1,2.2,.55],[sign*4.65,-1.1,-2.35],'real front retaining rail'));b([1.1,1.3,.65],[sign*4.7,-6.9,-2.3],'real deep retaining shoulder');}
 const floor=b([10.4,7.8,.65],[0,-3.9,2.3],'dielectric floor seated against rear PCB'),back=b([10.4,.8,4.6],[0,-7.4,.3],'deep actual insertion stop'),latch=b([4.8,1.8,.5],[0,-4.9,-2.375],'rear-side actual latch bridge');
 for(let i=0;i<4;i++){const x=(i-1.5)*2;contacts.push(b([.4,6.6,.4],[x,-4.3,.25],'retained square receiving contact '+(i+1),tin));returns.push(b([.4,.55,2.6],[x,-7.5,1.45],'actual bent contact riser '+(i+1),tin));feet.push(b([.4,2.7,.4],[x,-8.65,2.65],'actual retained solder foot '+(i+1),tin));tails.push(b([.4,.4,1.35],[x,-9.8,3.0],'actual through-board retained tail '+(i+1),tin));}
 const port=host.add(new Port({id,label:'Original HEX · '+cfg.role+' / HY2.0-4P',connector:'grove',position:cfg.position,quaternion:portQuaternion(cfg.face),hitSize:[12,1,5.25],pinGrid:{cols:4,rows:1,pitch:2,center:[0,.25],order:col=>col+1},pins:cfg.pins.map((name,i)=>({n:i+1,name})),meta:{role:'visual-connector',face:cfg.face,physicalRole:cfg.role,contactNumbering:'Own local mechanical left-to-right order;IN diagram top-to-bottom GND/VCC/DATA/unlabelled;OUT reversed physical drawing direction;PWR only first GND/VCC labels established.',scope:'Three actual4contact receivers;literal documentary labels only,no electrical routing,data cascade,power behavior or firmware. Unlabelled contacts have no assigned function.'}}));return{frame,parts,walls,floor,back,latch,contacts,returns,feet,tails,port};}
